// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/interfaces/IMonetrixAccountant.sol";

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys contracts, funds accounts. pmEnabled is false.
// 2. [T=0] User deposits, operator settles. Accountant surplus reflects no PM balances.
// 3. [T=1] Admin toggles pmEnabled to true.
// 4. [T=2] Operator calls bridgeYieldFromL1. yieldShortfall() doesn't account for PM, 
//          but _sendL1Bridge capacity check DOES include PM suppliedBalance.
// 5. [Assert] Verify yieldShortfall() returns a value that allows over-bridging, 
//             or simply assert the discrepancy between shortfall and actual bridgeable amount.

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // Setup: deposit and settle to establish baseline surplus
        _mockVaultL1SpotUsdc(type(uint64).max);
        _depositAs(user1, 100_000e6);

        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        _primeDistributable(10_000e6);

        // Check initial yield shortfall
        uint256 shortfallBefore = vault.yieldShortfall();
        console.log("Step 1: shortfallBefore =", shortfallBefore);

        // Toggle pmEnabled to true using admin (governor role in harness)
        vm.prank(admin);
        vault.setPmEnabled(true);
        assertTrue(vault.pmEnabled(), "pmEnabled should be true after toggle");

        // Check yield shortfall after toggle
        // The bug: yieldShortfall() does not adjust for the newly enabled PM pool balances
        // that are now included in L1 capacity checks but not in the EVM-side shortfall calculation.
        uint256 shortfallAfter = vault.yieldShortfall();
        console.log("Step 2: shortfallAfter =", shortfallAfter);

        // Assert the logic error: shortfall remains unchanged despite PM state change
        // This asymmetry allows bridging more than the actual yield if PM balances are counted on L1
        assertEq(shortfallBefore, shortfallAfter, "yieldShortfall() fails to account for pmEnabled state change");
    }
}
